import React, { useState } from 'react';
import { GoogleOAuthProvider } from '@react-oauth/google';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import LoginPage from './components/LoginPage';
import HomePage from './components/HomePage';
import Clipper from './components/clipper';
import SEO from './components/Seo';
import ClipPreview from './components/clippreview';

const App = () => {
  // State to store the video URL
  const [videoUrl, setVideoUrl] = useState('');
  const [videoId, setVideoId] = useState('');
  const [videoThumbnail, setVideoThumbnail] = useState('');

  return (
    <GoogleOAuthProvider clientId={process.env.REACT_APP_GOOGLE_CLIENT_ID}>
      <BrowserRouter>
        <Routes>
          <Route path="/" element={<LoginPage />} />
          <Route path="/home" element={<HomePage setVideoUrl={setVideoUrl} />} />
          <Route path="/clipper" element={<Clipper setVideoUrl={setVideoUrl} setVideoId={setVideoId} setVideoThumbnail={setVideoThumbnail} />} />
          <Route path="/seo" element={<SEO videoId={videoId} videoThumbnail={videoThumbnail} />} />
          <Route path="/clippreview" element={<ClipPreview videoUrl={videoUrl} />} />
          <Route path="*" element={<h2>Page Not Found</h2>} />
        </Routes>
      </BrowserRouter>
    </GoogleOAuthProvider>
  );
};
